const styles = `
.userpage-container {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 32px;
  padding-left: 10%;
  padding-top: 64px;
  min-height: 80vh;
  margin-top: 64px;
}
.prof-modal {
  position: relative;
  width: 220px;
  height: 320px;
  background: #fff;
  border-radius: 18px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.12);
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: transform 0.2s, box-shadow 0.2s, width 0.3s, height 0.3s;
  cursor: pointer;
  overflow: hidden;
}
.prof-modal:hover {
  transform: scale(1.07);
  box-shadow: 0 8px 32px rgba(0,0,0,0.18);
}
.prof-modal.expanded {
  width: 340px;
  height: 420px;
  z-index: 10;
  box-shadow: 0 12px 48px rgba(0,0,0,0.22);
  transform: scale(1.12);
}
.prof-image {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  margin-top: 24px;
  object-fit: cover;
  background: #eee;
  transition: width 0.3s, height 0.3s;
}
.prof-modal.expanded .prof-image {
  width: 150px;
  height: 150px;
}
.prof-name {
  margin: 18px 0 0 0;
  font-size: 1.3rem;
  font-weight: 600;
  text-align: center;
}
.prof-slots {
  position: absolute;
  bottom: 18px;
  right: 18px;
  background: #f5f5f5;
  padding: 7px 16px;
  border-radius: 16px;
  font-size: 1rem;
  color: #333;
  font-weight: 500;
  box-shadow: 0 2px 8px rgba(0,0,0,0.07);
}
.pogledaj-btn {
  position: absolute;
  bottom: 18px;
  left: 18px;
  background: #1976d2;
  color: #fff;
  border: none;
  border-radius: 14px;
  padding: 8px 20px;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s, box-shadow 0.2s;
  box-shadow: 0 2px 8px rgba(25, 118, 210, 0.15);
}
.pogledaj-btn:hover {
  background: #1251a3;
}
`;

const UserPage = () => {
  const [expandedId, setExpandedId] = useState(null);

  React.useEffect(() => {
    if (!document.getElementById('userpage-styles')) {
      const style = document.createElement('style');
      style.id = 'userpage-styles';
      style.innerHTML = styles;
      document.head.appendChild(style);
    }
  }, []);

  return (
    <>
      <NavBar />
      <div className="userpage-container">
        {professors.map((prof) => (
          <div
            key={prof.id}
            className={`prof-modal${expandedId === prof.id ? ' expanded' : ''}`}
            onClick={() => setExpandedId(expandedId === prof.id ? null : prof.id)}
          >
            <img src={prof.image} alt={prof.name} className="prof-image" />
            <h2 className="prof-name">{prof.name}</h2>
            <span className="prof-slots">{prof.slots}</span>
            <button
              className="pogledaj-btn"
              onClick={e => {
                e.stopPropagation();
                alert(`Pogledaj detalje za ${prof.name}`);
              }}
            >
              Pogledaj
            </button>
          </div>
        ))}
      </div>
    </>
  );
};

export default UserPage;
